function readTarget(r) {
    const f = {};
    f.state = r.u16();
    f.swd = r.u16();
    f.targetid = r.u32();
    f.firmware = r.u32();
    f.fwFlags = r.u16();
    f.services = r.variable(4, () => readServiceEntry(r));
    return f;
}

function writeTarget(w, f) {
    w.u16(f.state);
    w.u16(f.swd);
    w.u32(f.targetid);
    w.u32(f.firmware);
    w.u16(f.fwFlags);
    w.u16((f.services ?? []).length * 4);
    for (const e of f.services ?? []) {
        writeServiceEntry(w, e);
    }
}

