function readIdentify(r) {
    const f = {};
    f.flags = r.u16();
    f.count = r.u16();
    f.firmware = r.list(f.count, () => r.u32());
    return f;
}

function writeIdentify(w, f) {
    w.u16(f.flags);
    w.u16(f.count ?? (f.firmware ?? []).length);
    for (const e of f.firmware ?? []) {
        w.u32(e);
    }
}

