function readHwInfo(r) {
    const f = {};
    f.chip = r.u16();
    f.chipRev = r.bytesOf(2);
    f.flash = r.u32();
    f.psram = r.u32();
    f.mac = r.bytesOf(6);
    f.model = r.u16();
    f.serial = r.left() >= 16 ? r.padded(16) : null;
    return f;
}

function writeHwInfo(w, f) {
    w.u16(f.chip);
    w.bytesOf(f.chipRev, 2);
    w.u32(f.flash);
    w.u32(f.psram);
    w.bytesOf(f.mac, 6);
    w.u16(f.model);
    w.padded(f.serial, 16);
}

