function readFwInfo(r) {
    const f = {};
    f.version = r.bytesOf(3);
    r.bytesOf(1);
    f.bootloader = r.u16();
    r.bytesOf(2);
    f.wamr = r.bytesOf(3);
    r.bytesOf(1);
    f.commit = r.left() >= 2 ? r.text() : null;
    return f;
}

function writeFwInfo(w, f) {
    w.bytesOf(f.version, 3);
    w.bytesOf(null, 1);
    w.u16(f.bootloader);
    w.bytesOf(null, 2);
    w.bytesOf(f.wamr, 3);
    w.bytesOf(null, 1);
    w.text(f.commit);
}

