function readWifiSta(r) {
    const f = {};
    f.state = r.u16();
    f.rssi = r.i8();
    r.bytesOf(1);
    f.ipv4 = r.bytesOf(4);
    f.ipv6 = r.bytesOf(16);
    f.ipv4Mode = r.u16();
    f.flags = r.u16();
    f.ipv4Netmask = r.bytesOf(4);
    f.ipv4Gateway = r.bytesOf(4);
    f.ipv4Dns = r.bytesOf(4);
    f.reason = r.u16();
    f.ssid = r.text();
    return f;
}

function writeWifiSta(w, f) {
    w.u16(f.state);
    w.i8(f.rssi);
    w.bytesOf(null, 1);
    w.bytesOf(f.ipv4, 4);
    w.bytesOf(f.ipv6, 16);
    w.u16(f.ipv4Mode);
    w.u16(f.flags);
    w.bytesOf(f.ipv4Netmask, 4);
    w.bytesOf(f.ipv4Gateway, 4);
    w.bytesOf(f.ipv4Dns, 4);
    w.u16(f.reason);
    w.text(f.ssid);
}

