export function decodeResetPins(p) {
    const r = new FieldReader(p);
    const f = readResetPins(r);
    return r.short ? null : f;
}

/**
 * Encodes RESET_PINS's fields.
 * @param {object} f - the fields. A missing field is 0 or empty
 * @returns {Uint8Array}
 */
export function encodeResetPins(f) {
    const w = new FieldWriter();
    writeResetPins(w, f);
    return w.bytes();
}

